require_once __DIR__ . '/../Database.php';
require_once __DIR__ . '/../Response.php';
require_once __DIR__ . '/../SystemLog.php';
require_once __DIR__ . '/../Utils/RateLimiter.php';

class SecurityController
{
    private static bool $tableEnsured = false;

    public function __construct()
    {
        if (!self::$tableEnsured) {
            try {
                $db = Database::getConnection();
                $this->ensureBannedIpsTable($db);
                self::$tableEnsured = true;
            } catch (\Throwable $e) {
            error_log("Suppressed exception in " . __METHOD__ . ": " . $e->getMessage());
        }
        }
    }

    public function ensureBannedIpsTable(?PDO $db = null): void
    {
        $db = $db ?? Database::getConnection();
        $db->exec("CREATE TABLE IF NOT EXISTS banned_ips (
            id INT AUTO_INCREMENT PRIMARY KEY,
            ip_address VARCHAR(45) NOT NULL UNIQUE,
            reason VARCHAR(255) NOT NULL,
            ban_type ENUM('permanent', 'temporary') NOT NULL DEFAULT 'temporary',
            banned_by INT NULL,
            banned_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
            expires_at DATETIME NULL DEFAULT NULL,
            attempts_blocked INT NOT NULL DEFAULT 0,
            status ENUM('active', 'revoked', 'expired') NOT NULL DEFAULT 'active',
            notes TEXT NULL,
            created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
            updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
            UNIQUE KEY uniq_banned_ip (ip_address),
            INDEX idx_ban_status_expiry (status, expires_at),
            INDEX idx_ban_banned_by (banned_by),
            INDEX idx_ban_created (created_at),
            FOREIGN KEY (banned_by) REFERENCES users(id) ON DELETE SET NULL
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
    }

    /**
     * Get live threat monitoring feed, anomaly classifications, and active lockouts.
     */
    public function threatMonitor(): void
    {
        $isAdmin = !empty($_SESSION['is_admin']) || ($_SESSION['role'] ?? '') === 'admin';
        if (!$isAdmin) {
            Response::json(['error' => 'Admin privileges required'], 403);
            return;
        }

        $db = Database::getConnection();

        // 1. Fetch Active Bans
        $bansStmt = $db->query("
            SELECT b.*, u.username as banned_by_username
            FROM banned_ips b
            LEFT JOIN users u ON b.banned_by = u.id
            ORDER BY b.created_at DESC
            LIMIT 100
        ");
        $allBans = $bansStmt->fetchAll(PDO::FETCH_ASSOC);

        $activeBannedIps = [];
        $activeBansCount = 0;
        $totalBlockedAttempts = 0;
        $nowTs = time();

        foreach ($allBans as &$ban) {
            $totalBlockedAttempts += (int)$ban['attempts_blocked'];
            if ($ban['status'] === 'active') {
                if ($ban['ban_type'] === 'temporary' && $ban['expires_at'] && strtotime($ban['expires_at']) <= $nowTs) {
                    $ban['status'] = 'expired';
                } else {
                    $activeBannedIps[$ban['ip_address']] = $ban;
                    $activeBansCount++;
                }
            }
        }
        unset($ban);

        // 2. Fetch Active Rate Limit Lockouts (Resilient to clock skew via DB TIMESTAMPDIFF & NOW)
        $limitsStmt = $db->query("
            SELECT id, ip_address, identifier, action_type, failed_attempts, first_attempt_at, last_attempt_at, locked_until,
                   TIMESTAMPDIFF(SECOND, NOW(), locked_until) AS db_remaining_seconds,
                   IF(locked_until IS NOT NULL AND locked_until > NOW(), 1, 0) AS db_is_locked
            FROM auth_rate_limits
            WHERE last_attempt_at >= DATE_SUB(NOW(), INTERVAL 24 HOUR)
            ORDER BY last_attempt_at DESC
            LIMIT 200
        ");
        $rateLimits = $limitsStmt->fetchAll(PDO::FETCH_ASSOC);

        $activeLockouts = [];
        $ipMap = [];

        foreach ($rateLimits as &$rl) {
            $ip = $rl['ip_address'];
            $isLocked = !empty($rl['db_is_locked']);
            $remainingSeconds = $isLocked ? max(1, (int)($rl['db_remaining_seconds'] ?? 1)) : 0;

            $rl['is_locked'] = $isLocked;
            $rl['remaining_seconds'] = $remainingSeconds;
            $rl['is_banned'] = isset($activeBannedIps[$ip]);

            if ($isLocked) {
                $activeLockouts[] = $rl;
            }

            if (!isset($ipMap[$ip])) {
                $ipMap[$ip] = [
                    'ip_address' => $ip,
                    'identifiers' => [],
                    'total_failed' => 0,
                    'action_types' => [],
                    'first_seen' => $rl['first_attempt_at'],
                    'last_seen' => $rl['last_attempt_at'],
                    'is_locked' => $isLocked,
                    'locked_until' => $rl['locked_until'],
                    'is_banned' => isset($activeBannedIps[$ip]),
                    'ban_id' => $activeBannedIps[$ip]['id'] ?? null
                ];
            }

            if (!empty($rl['identifier'])) {
                $ipMap[$ip]['identifiers'][] = $rl['identifier'];
            }
            $ipMap[$ip]['total_failed'] += (int)$rl['failed_attempts'];
            $ipMap[$ip]['action_types'][] = $rl['action_type'];
            if ($isLocked) {
                $ipMap[$ip]['is_locked'] = true;
                $ipMap[$ip]['locked_until'] = $rl['locked_until'];
            }
        }
        unset($rl);

        // 3. Classify Threats
        $threats = [];
        foreach ($ipMap as $ip => $data) {
            $uniqueTargets = array_values(array_unique(array_filter($data['identifiers'])));
            $distinctCount = count($uniqueTargets);
            $actionTypes = array_unique($data['action_types']);
            $totalFailed = $data['total_failed'];

            $threatType = 'suspicious_probe';
            $severity = 'medium';
            $description = "Detected {$totalFailed} failed authentication attempts.";

            if (in_array('master_recovery', $actionTypes, true) && $totalFailed >= 2) {
                $threatType = 'recovery_fuzzing';
                $severity = 'critical';
                $description = "Repeated failed attempts probing root master emergency recovery key ({$totalFailed} attempts).";
            } elseif (in_array('user_recovery', $actionTypes, true) && $totalFailed >= 2) {
                $threatType = 'recovery_fuzzing';
                $severity = 'high';
                $description = "Multiple failed user recovery key attempts ({$totalFailed} attempts).";
            } elseif ($distinctCount >= 3 && $totalFailed >= 4) {
                $threatType = 'credential_stuffing';
                $severity = 'critical';
                $description = "Testing multiple user accounts from single IP ({$distinctCount} accounts: " . implode(', ', array_slice($uniqueTargets, 0, 4)) . ").";
            } elseif ($distinctCount >= 2 && $totalFailed >= 3) {
                $threatType = 'credential_stuffing';
                $severity = 'high';
                $description = "Multi-account probe across (" . implode(', ', $uniqueTargets) . ").";
            } elseif ($totalFailed >= 5) {
                $threatType = 'targeted_brute_force';
                $severity = 'high';
                $target = !empty($uniqueTargets[0]) ? $uniqueTargets[0] : 'Single Account';
                $description = "Aggressive password guessing targeted at {$target}.";
            } elseif ($data['is_locked']) {
                $threatType = 'cooldown_violation';
                $severity = 'high';
                $description = "Active lockout in effect due to repeated threshold breaches.";
            } elseif (in_array('master_recovery', $actionTypes, true) || in_array('user_recovery', $actionTypes, true)) {
                $threatType = 'suspicious_probe';
                $severity = 'medium';
                $description = "Single isolated failed recovery key attempt.";
            }

            $labelMap = [
                'recovery_fuzzing' => 'Recovery Token Fuzzing',
                'credential_stuffing' => 'Credential Stuffing Probe',
                'targeted_brute_force' => 'Targeted Brute Force',
                'cooldown_violation' => 'Lockout / Cooldown Violation',
                'suspicious_probe' => 'Suspicious Authentication Probe'
            ];

            $isLocal = ($ip === '127.0.0.1' || $ip === '::1' || !filter_var($ip, FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE));

            $threats[] = [
                'ip_address' => $ip,
                'is_local' => $isLocal,
                'is_local_ip' => $isLocal,
                'ip_type' => $isLocal ? 'Local LAN / Direct Server Host' : 'Public Internet Connection',
                'threat_type' => $threatType,
                'attack_classification' => $threatType,
                'classification_label' => $labelMap[$threatType] ?? 'Security Incident',
                'severity' => $severity,
                'description' => $description,
                'distinct_targets' => $distinctCount,
                'target_users' => $uniqueTargets,
                'targeted_accounts' => $uniqueTargets,
                'failed_attempts' => $totalFailed,
                'total_failed_attempts' => $totalFailed,
                'action_types' => array_values($actionTypes),
                'first_seen' => $data['first_seen'],
                'last_seen' => $data['last_seen'],
                'is_locked' => $data['is_locked'],
                'locked_until' => $data['locked_until'],
                'is_banned' => $data['is_banned'],
                'ban_id' => $data['ban_id']
            ];
        }

        // Sort threats: Critical first, then High, then Most Recent
        usort($threats, function ($a, $b) {
            $sevOrder = ['critical' => 3, 'high' => 2, 'medium' => 1, 'low' => 0];
            $diff = ($sevOrder[$b['severity']] ?? 0) <=> ($sevOrder[$a['severity']] ?? 0);
            if ($diff !== 0) return $diff;
            return strcmp($b['last_seen'], $a['last_seen']);
        });

        $summaryData = [
            'active_bans_count' => $activeBansCount,
            'active_banned_ips' => $activeBansCount,
            'active_lockouts_count' => count($activeLockouts),
            'active_threats_detected' => count($threats),
            'threats_detected_24h' => count($threats),
            'total_blocked_attempts' => $totalBlockedAttempts,
            'total_blocked_probes' => $totalBlockedAttempts,
            'client_ip' => RateLimiter::getClientIp()
        ];

        Response::json([
            'ok' => true,
            'summary' => $summaryData,
            'stats' => $summaryData,
            'threats' => $threats,
            'active_lockouts' => $activeLockouts,
            'banned_ips' => $allBans
        ]);
    }

    /**
     * Ban an IP address (Manual or Quick Ban).
     */
    public function banIp(?string $directIp = null, ?int $directDuration = null, ?string $directUnit = null, ?string $directReason = null): void
    {
        try {
            $isAdmin = !empty($_SESSION['is_admin']) || ($_SESSION['role'] ?? '') === 'admin';
        if (!$isAdmin) {
            Response::json(['error' => 'Admin privileges required'], 403);
            return;
        }

        $input = json_decode(file_get_contents('php://input'), true) ?? $_POST;
        $ip = $directIp ?? trim($input['ip_address'] ?? '');
        $reason = $directReason ?? trim($input['reason'] ?? 'Threat detection mitigation');
        $banType = ($input['ban_type'] ?? '') === 'permanent' ? 'permanent' : 'temporary';
        $durationSeconds = (int)($input['duration_seconds'] ?? 86400); // default 24h
        
        $durationVal = $directDuration ?? ($input['duration'] ?? null);
        $durationUnit = $directUnit ?? ($input['duration_unit'] ?? null);

        if ($durationVal !== null) {
            $dur = (int)$durationVal;
            $unit = $durationUnit ?? 'hours';
            if ($unit === 'permanent' || $dur === 0) {
                $banType = 'permanent';
            } elseif ($unit === 'days') {
                $durationSeconds = $dur * 86400;
            } else {
                $durationSeconds = $dur * 3600;
            }
        }
        $notes = trim($input['notes'] ?? '');

        if (empty($ip) || !filter_var($ip, FILTER_VALIDATE_IP)) {
            Response::json(['error' => 'Invalid IP address format'], 400);
            return;
        }

        // Immunity Protection: Do not allow banning loopback or current admin's own IP
        $currentIp = RateLimiter::getClientIp();
        $isLoopback = RateLimiter::isLocalhost($ip) || $ip === '127.0.0.1' || $ip === '::1' || str_starts_with($ip, '127.') || $ip === '::ffff:127.0.0.1';
        if ($isLoopback) {
            Response::json([
                'error' => 'Loopback localhost IP (127.0.0.1 / ::1) is strictly protected by system immunity and cannot be banned',
                'is_loopback' => true
            ], 400);
            return;
        }
        if ($ip === $currentIp) {
            Response::json([
                'error' => 'You cannot ban your own active connection IP address (' . $currentIp . ')',
                'is_self' => true
            ], 400);
            return;
        }

        $expiresAt = null;
        if ($banType === 'temporary') {
            $durationSeconds = max(60, $durationSeconds);
            $expiresAt = date('Y-m-d H:i:s', time() + $durationSeconds);
        }

        $db = Database::getConnection();
        $adminId = (int)($_SESSION['user_id'] ?? 0);
        $adminName = $_SESSION['username'] ?? "Admin #{$adminId}";

        $stmt = $db->prepare("
            INSERT INTO banned_ips (ip_address, reason, ban_type, banned_by, banned_at, expires_at, status, notes, created_at, updated_at)
            VALUES (:ip, :reason, :ban_type, :banned_by, NOW(), :expires_at, 'active', :notes, NOW(), NOW())
            ON DUPLICATE KEY UPDATE
                reason = VALUES(reason),
                ban_type = VALUES(ban_type),
                banned_by = VALUES(banned_by),
                banned_at = NOW(),
                expires_at = VALUES(expires_at),
                status = 'active',
                notes = VALUES(notes),
                updated_at = NOW()
        ");

        $stmt->execute([
            'ip' => $ip,
            'reason' => $reason,
            'ban_type' => $banType,
            'banned_by' => $adminId ?: null,
            'expires_at' => $expiresAt,
            'notes' => $notes
        ]);

        $banId = (int)$db->lastInsertId();
        if (!$banId) {
            $fetchStmt = $db->prepare("SELECT id FROM banned_ips WHERE ip_address = :ip LIMIT 1");
            $fetchStmt->execute(['ip' => $ip]);
            $banId = (int)$fetchStmt->fetchColumn();
        }

        // Privacy-Aware Audit Log (Rule 8)
        SystemLog::write(
            'security',
            'ip_banned',
            $banId,
            $ip,
            json_encode([
                'ip' => $ip,
                'ban_type' => $banType,
                'reason' => $reason,
                'expires_at' => $expiresAt,
                'banned_by' => $adminName,
                'notes' => $notes
            ])
        );

        Response::json([
            'ok' => true,
            'message' => "IP {$ip} has been blacklisted successfully",
            'ban' => [
                'id' => $banId,
                'ip_address' => $ip,
                'reason' => $reason,
                'ban_type' => $banType,
                'expires_at' => $expiresAt,
                'banned_by_username' => $adminName,
                'status' => 'active'
            ]
        ]);
        } catch (\Throwable $e) {
            error_log('[SECURITY BAN IP ERROR] ' . $e->getMessage());
            Response::json(['error' => 'An internal error occurred while blacklisting the IP address'], 500);
        }
    }

    /**
     * Revoke an active IP ban.
     */
    public function unbanIp(?int $directId = null, ?string $directIp = null, ?string $directReason = null): void
    {
        try {
            $isAdmin = !empty($_SESSION['is_admin']) || ($_SESSION['role'] ?? '') === 'admin';
        if (!$isAdmin) {
            Response::json(['error' => 'Admin privileges required'], 403);
            return;
        }

        $input = json_decode(file_get_contents('php://input'), true) ?? $_POST;
        $id = $directId ?? (int)($input['id'] ?? 0);
        $ip = $directIp ?? trim($input['ip_address'] ?? '');
        $reason = $directReason ?? trim($input['reason'] ?? 'Ban lifted by administrator');

        $db = Database::getConnection();

        if ($id > 0) {
            $findStmt = $db->prepare("SELECT id, ip_address FROM banned_ips WHERE id = :id LIMIT 1");
            $findStmt->execute(['id' => $id]);
        } elseif (!empty($ip)) {
            $findStmt = $db->prepare("SELECT id, ip_address FROM banned_ips WHERE ip_address = :ip LIMIT 1");
            $findStmt->execute(['ip' => $ip]);
        } else {
            Response::json(['error' => 'Ban ID or IP address required'], 400);
            return;
        }

        $ban = $findStmt->fetch(PDO::FETCH_ASSOC);
        if (!$ban) {
            // Check if IP is in auth_rate_limits instead of banned_ips
            if (!empty($ip)) {
                $rlStmt = $db->prepare("DELETE FROM auth_rate_limits WHERE ip_address = :ip");
                $rlStmt->execute(['ip' => $ip]);
                if ($rlStmt->rowCount() > 0) {
                    SystemLog::write('security', 'cooldown_cleared', 0, $ip, json_encode([
                        'ip' => $ip,
                        'unbanned_by' => $_SESSION['username'] ?? 'Admin',
                        'reason' => 'Rate limit cooldown cleared via unban'
                    ]));
                    Response::json([
                        'ok' => true,
                        'message' => "IP {$ip} rate limits and cooldown cleared successfully",
                        'ip_address' => $ip
                    ]);
                    return;
                }
            }
            Response::json(['error' => 'Ban record or rate limit lock not found for this IP'], 404);
            return;
        }

        $banId = (int)$ban['id'];
        $targetIp = $ban['ip_address'];

        // Revoke the ban
        $upStmt = $db->prepare("UPDATE banned_ips SET status = 'revoked', updated_at = NOW() WHERE id = :id");
        $upStmt->execute(['id' => $banId]);


