        // Also clean up rate limit entries for that IP so they aren't immediately blocked by residual locks
        $db->prepare("DELETE FROM auth_rate_limits WHERE ip_address = :ip")->execute(['ip' => $targetIp]);

        $adminId = (int)($_SESSION['user_id'] ?? 0);
        $adminName = $_SESSION['username'] ?? "Admin #{$adminId}";

        // Privacy-Aware Audit Log (Rule 8)
        SystemLog::write(
            'security',
            'ip_unbanned',
            $banId,
            $targetIp,
            json_encode([
                'ip' => $targetIp,
                'unbanned_by' => $adminName,
                'reason' => $reason
            ])
        );

        Response::json([
            'ok' => true,
            'message' => "IP {$targetIp} has been unbanned successfully",
            'ip_address' => $targetIp
        ]);
        } catch (\Throwable $e) {
            error_log('[SECURITY UNBAN IP ERROR] ' . $e->getMessage());
            Response::json(['error' => 'An internal error occurred while unbanning the IP address'], 500);
        }
    }

    /**
     * Instantly clear active rate-limit lockouts and reset attempt counters.
     * Allows administrators to unlock a friend or cashier in cooldown immediately.
     */
    public function clearCooldown(): void
    {
        try {
            $isAdmin = !empty($_SESSION['is_admin']) || ($_SESSION['role'] ?? '') === 'admin';
        if (!$isAdmin) {
            Response::json(['error' => 'Admin privileges required'], 403);
            return;
        }

        $input = json_decode(file_get_contents('php://input'), true) ?? $_POST;
        $ip = trim($input['ip_address'] ?? '');
        $identifier = trim($input['identifier'] ?? '');

        if (empty($ip) && empty($identifier)) {
            Response::json(['error' => 'IP address or username identifier required'], 400);
            return;
        }

        $db = Database::getConnection();
        if (!empty($ip) && !empty($identifier)) {
            $stmt = $db->prepare("DELETE FROM auth_rate_limits WHERE ip_address = :ip OR identifier = :ident");
            $stmt->execute(['ip' => $ip, 'ident' => $identifier]);
        } elseif (!empty($ip)) {
            $stmt = $db->prepare("DELETE FROM auth_rate_limits WHERE ip_address = :ip");
            $stmt->execute(['ip' => $ip]);
        } else {
            $stmt = $db->prepare("DELETE FROM auth_rate_limits WHERE identifier = :ident");
            $stmt->execute(['ident' => $identifier]);
        }

        $clearedRows = $stmt->rowCount();
        $adminName = $_SESSION['username'] ?? 'Admin';

        // Privacy-Aware Audit Log (Rule 8)
        SystemLog::write(
            'security',
            'cooldown_cleared',
            0,
            $ip ?: $identifier,
            json_encode([
                'ip'           => $ip,
                'identifier'   => $identifier,
                'cleared_rows' => $clearedRows,
                'cleared_by'   => $adminName
            ])
        );

        Response::json([
            'ok' => true,
            'message' => 'Cooldown and rate limits cleared successfully',
            'cleared_rows' => $clearedRows
        ]);
        } catch (\Throwable $e) {
            error_log('[SECURITY CLEAR COOLDOWN ERROR] ' . $e->getMessage());
            Response::json(['error' => 'An internal error occurred while clearing cooldown'], 500);
        }
    }

    /**
     * Emergency on-screen admin unlock for a blacklisted terminal.
     * Authenticates with admin credentials or Super Admin Master Recovery Key.
     */
    public function emergencyUnban(): void
    {
        $input = json_decode(file_get_contents('php://input'), true) ?? $_POST;
        $username = trim($input['username'] ?? '');
        $password = trim($input['password'] ?? '');
        $masterKey = trim($input['master_key'] ?? '');
        $db = Database::getConnection();
        $clientIp = RateLimiter::getClientIp();
        $identifier = !empty($masterKey) ? 'emergency_unban_master_key' : (!empty($username) ? $username : 'emergency_unban_attempt');

        // Check Rate Limiter lock
        $lock = RateLimiter::checkLock($db, 'emergency_unban', $identifier, $clientIp);
        if ($lock !== null) {
            http_response_code(429);
            header('Retry-After: ' . $lock['remaining_seconds']);
            Response::json([
                'error' => "Too many failed attempts. Emergency unban is locked for {$lock['remaining_seconds']} seconds.",
                'remaining_seconds' => $lock['remaining_seconds']
            ], 429);
            return;
        }

        $authenticated = false;
        $adminName = '';

        // Option A: Verify Admin credentials
        if (!empty($username) && !empty($password)) {
            $userStmt = $db->prepare("SELECT id, username, password_hash, is_admin FROM users WHERE username = :u AND deleted_at IS NULL LIMIT 1");
            $userStmt->execute(['u' => $username]);
            $user = $userStmt->fetch(PDO::FETCH_ASSOC);
            if ($user && !empty($user['is_admin']) && password_verify($password, $user['password_hash'])) {
                $authenticated = true;
                $adminName = $user['username'];
            }
        }

        // Option B: Verify Super Admin Master Recovery Key (Requires active admin account with deleted_at IS NULL)
        if (!$authenticated && !empty($masterKey)) {
            $adminCheck = $db->query("SELECT id FROM users WHERE is_admin = 1 AND deleted_at IS NULL LIMIT 1");
            if ($adminCheck && $adminCheck->fetchColumn()) {
                $setStmt = $db->query("SELECT recovery_code_hash, recovery_code_plain FROM settings LIMIT 1");
                $set = $setStmt ? $setStmt->fetch(PDO::FETCH_ASSOC) : null;
                if ($set) {
                    $plainMaster = class_exists('RecoveryCrypto') ? RecoveryCrypto::decrypt($set['recovery_code_plain'] ?? null) : ($set['recovery_code_plain'] ?? null);
                    if ((!empty($plainMaster) && hash_equals($plainMaster, $masterKey)) ||
                        (!empty($set['recovery_code_hash']) && password_verify($masterKey, $set['recovery_code_hash']))) {
                        $authenticated = true;
                        $adminName = 'Master Key Override';
                    }
                }
            }
        }

        if (!$authenticated) {
            $fail = RateLimiter::recordFailure($db, 'emergency_unban', $identifier, $clientIp, 5, 300);
            SystemLog::write('security', 'emergency_unban_failed', 0, $clientIp, json_encode([
                'attempted_user'  => $username,
                'used_master_key' => !empty($masterKey),
                'failed_attempts' => $fail['failed_attempts']
            ]));
            $statusCode = $fail['is_locked'] ? 429 : 401;
            http_response_code($statusCode);
            Response::json([
                'error' => $fail['is_locked']
                    ? "Too many failed attempts. Emergency unban is locked for {$fail['remaining_seconds']} seconds."
                    : 'Invalid administrator credentials or master recovery key',
                'remaining_attempts' => $fail['remaining_attempts'] ?? 0
            ], $statusCode);
            return;
        }

        // Reset rate limiter on successful authentication
        RateLimiter::reset($db, 'emergency_unban', $identifier, $clientIp);
        RateLimiter::reset($db, 'emergency_unban', 'emergency_unban_master_key', $clientIp);

        // Revoke ban for client IP
        $db->prepare("UPDATE banned_ips SET status = 'revoked', updated_at = NOW() WHERE ip_address = :ip")->execute(['ip' => $clientIp]);
        // Clear rate limits for client IP
        $db->prepare("DELETE FROM auth_rate_limits WHERE ip_address = :ip")->execute(['ip' => $clientIp]);

        // Privacy-Aware Audit Log (Rule 8)
        SystemLog::write(
            'security',
            'emergency_unban',
            0,
            $clientIp,
            json_encode([
                'ip' => $clientIp,
                'unbanned_by' => $adminName,
                'reason' => 'Emergency on-screen admin unlock'
            ])
        );

        Response::json([
            'ok' => true,
            'message' => "IP {$clientIp} unbanned successfully! Access restored."
        ]);
    }

    /**
     * Get list of banned IPs.
     */
    public function getBannedIps(): void
    {
        $isAdmin = !empty($_SESSION['is_admin']) || ($_SESSION['role'] ?? '') === 'admin';
        if (!$isAdmin) {
            Response::json(['error' => 'Admin privileges required'], 403);
            return;
        }

        $db = Database::getConnection();
        $stmt = $db->query("
            SELECT b.*, u.username as banned_by_username
            FROM banned_ips b
            LEFT JOIN users u ON b.banned_by = u.id
            ORDER BY b.created_at DESC
            LIMIT 200
        ");
        $bans = $stmt->fetchAll(PDO::FETCH_ASSOC);

        Response::json([
            'ok' => true,
            'banned_ips' => $bans
        ]);
    }

    /**
     * Threat Forensics Deep Investigation endpoint by IP address.
     */
    public function threatForensics(?string $directIp = null): void
    {
        $isAdmin = !empty($_SESSION['is_admin']) || ($_SESSION['role'] ?? '') === 'admin';
        if (!$isAdmin) {
            Response::json(['error' => 'Admin privileges required to view threat forensics'], 403);
            return;
        }

        $rawInput = trim($directIp ?? ($_GET['ip'] ?? ''));
        if ($rawInput === '') {
            Response::json(['error' => 'IP address parameter is required'], 400);
            return;
        }

        $db = Database::getConnection();

        $targetIp = $rawInput;
        if (is_numeric($rawInput)) {
            $stmtLog = $db->prepare("SELECT ip_address FROM system_logs WHERE id = :id LIMIT 1");
            $stmtLog->execute(['id' => (int)$rawInput]);
            $resolvedIp = $stmtLog->fetchColumn();
            if (!empty($resolvedIp)) {
                $targetIp = $resolvedIp;
            }
        }

        // 1. Fetch all rate limit entries for this IP
        $stmt = $db->prepare("
            SELECT *, 
                   TIMESTAMPDIFF(SECOND, NOW(), locked_until) AS db_remaining_seconds,
                   IF(locked_until IS NOT NULL AND locked_until > NOW(), 1, 0) AS db_is_locked
            FROM auth_rate_limits 
            WHERE ip_address = :ip 
            ORDER BY last_attempt_at DESC
        ");
        $stmt->execute(['ip' => $targetIp]);
        $rateLimits = $stmt->fetchAll(PDO::FETCH_ASSOC);

        // 2. Fetch latest user agent and user info from login_history
        $hStmt = $db->prepare("
            SELECT lh.*, u.username as history_username 
            FROM login_history lh 
            LEFT JOIN users u ON lh.user_id = u.id 
            WHERE lh.ip_address = :ip 
            ORDER BY lh.id DESC 
            LIMIT 1
        ");
        $hStmt->execute(['ip' => $targetIp]);
        $history = $hStmt->fetch(PDO::FETCH_ASSOC);

        // 3. Fetch active ban info if any
        $bStmt = $db->prepare("
            SELECT b.*, u.username as banned_by_username 
            FROM banned_ips b 
            LEFT JOIN users u ON b.banned_by = u.id 
            WHERE b.ip_address = :ip AND b.status = 'active' 
              AND (b.expires_at IS NULL OR b.expires_at > NOW()) 
            LIMIT 1
        ");
        $bStmt->execute(['ip' => $targetIp]);
        $banInfo = $bStmt->fetch(PDO::FETCH_ASSOC) ?: null;

        // 4. Fetch recent system logs associated with this IP
        $lStmt = $db->prepare("
            SELECT id, user_id, username, module, action, entity_id, entity_name, details, ip_address, created_at 
            FROM system_logs 
            WHERE ip_address = :ip 
            ORDER BY id DESC 
            LIMIT 15
        ");
        $lStmt->execute(['ip' => $targetIp]);
        $recentLogs = $lStmt->fetchAll(PDO::FETCH_ASSOC);

        // Calculate aggregated telemetry
        $totalFailed = 0;
        $uniqueTargets = [];
        $actionTypes = [];
        $firstSeen = null;
        $lastSeen = null;
        $isLocked = false;
        $lockedUntil = null;
        $nowTs = time();

        foreach ($rateLimits as $rl) {
            $totalFailed += (int)$rl['failed_attempts'];
            if (!empty($rl['identifier'])) {
                $uniqueTargets[] = $rl['identifier'];
            }
            $actionTypes[] = $rl['action_type'];
            if ($firstSeen === null || strcmp($rl['first_attempt_at'], $firstSeen) < 0) {
                $firstSeen = $rl['first_attempt_at'];
            }
            if ($lastSeen === null || strcmp($rl['last_attempt_at'], $lastSeen) > 0) {
                $lastSeen = $rl['last_attempt_at'];
            }
            if (!empty($rl['db_is_locked'])) {
                $isLocked = true;
                if ($lockedUntil === null || strcmp((string)$rl['locked_until'], (string)$lockedUntil) > 0) {
                    $lockedUntil = $rl['locked_until'];
                }
            }
        }

        $uniqueTargets = array_values(array_unique(array_filter($uniqueTargets)));
        $distinctCount = count($uniqueTargets);
        $actionTypes = array_values(array_unique($actionTypes));

        // Attack Classification
        $threatType = 'suspicious_probe';
        $severity = 'medium';
        $description = "Detected {$totalFailed} failed authentication attempts.";

        if (in_array('master_recovery', $actionTypes, true) && $totalFailed >= 2) {
            $threatType = 'recovery_fuzzing';
            $severity = 'critical';
            $description = "Repeated failed attempts probing root master emergency recovery key ({$totalFailed} attempts).";
        } elseif (in_array('user_recovery', $actionTypes, true) && $totalFailed >= 2) {
            $threatType = 'recovery_fuzzing';
            $severity = 'high';
            $description = "Multiple failed user recovery key attempts ({$totalFailed} attempts).";
        } elseif ($distinctCount >= 3 && $totalFailed >= 4) {
            $threatType = 'credential_stuffing';
            $severity = 'critical';
            $description = "Testing multiple user accounts from single IP ({$distinctCount} accounts: " . implode(', ', array_slice($uniqueTargets, 0, 4)) . ").";
        } elseif ($distinctCount >= 2 && $totalFailed >= 3) {
            $threatType = 'credential_stuffing';
            $severity = 'high';
            $description = "Multi-account probe across (" . implode(', ', $uniqueTargets) . ").";
        } elseif ($totalFailed >= 5) {
            $threatType = 'targeted_brute_force';
            $severity = 'high';
            $target = !empty($uniqueTargets[0]) ? $uniqueTargets[0] : 'Single Account';
            $description = "Aggressive password guessing targeted at {$target}.";
        } elseif ($isLocked) {
            $threatType = 'cooldown_violation';
            $severity = 'high';
            $description = "Active lockout in effect due to repeated threshold breaches.";
        } elseif (in_array('master_recovery', $actionTypes, true) || in_array('user_recovery', $actionTypes, true)) {
            $threatType = 'suspicious_probe';
            $severity = 'medium';
            $description = "Single isolated failed recovery key attempt.";
        }

        $labelMap = [
            'recovery_fuzzing' => 'Recovery Token Fuzzing',
            'credential_stuffing' => 'Credential Stuffing Probe',
            'targeted_brute_force' => 'Targeted Brute Force',
            'cooldown_violation' => 'Lockout / Cooldown Violation',
            'suspicious_probe' => 'Suspicious Authentication Probe'
        ];

        // Parse User-Agent
        $uaString = ($history && !empty($history['user_agent'])) ? $history['user_agent'] : 'Unknown Browser / HTTP Client';
        $os = 'Unknown OS';
        if (stripos($uaString, 'Windows NT 10.0') !== false) $os = 'Windows 10 / 11';
        elseif (stripos($uaString, 'Windows') !== false) $os = 'Windows PC';
        elseif (stripos($uaString, 'Macintosh') !== false || stripos($uaString, 'Mac OS X') !== false) $os = 'macOS (Apple Mac)';
        elseif (stripos($uaString, 'iPhone') !== false) $os = 'iPhone (iOS)';
        elseif (stripos($uaString, 'iPad') !== false) $os = 'iPad (iPadOS)';
        elseif (stripos($uaString, 'Android') !== false) $os = 'Android Device';
        elseif (stripos($uaString, 'Linux') !== false) $os = 'Linux Device';

        $browser = 'Unknown Browser';
        if (stripos($uaString, 'Edg/') !== false) $browser = 'Microsoft Edge';
        elseif (stripos($uaString, 'Chrome/') !== false && stripos($uaString, 'Safari/') !== false) $browser = 'Google Chrome';
        elseif (stripos($uaString, 'Safari/') !== false && stripos($uaString, 'Chrome/') === false) $browser = 'Apple Safari';
        elseif (stripos($uaString, 'Firefox/') !== false) $browser = 'Mozilla Firefox';

        // Parse Local LAN vs Public
        $isLocal = ($targetIp === '127.0.0.1' || $targetIp === '::1' || !filter_var($targetIp, FILTER_VALIDATE_IP, FILTER_FLAG_NO_PRIV_RANGE | FILTER_FLAG_NO_RES_RANGE));

        // Format recent events for UI display
        $formattedEvents = [];
        foreach ($recentLogs as $log) {
            $detailsDecoded = json_decode((string)$log['details'], true);
            $formattedEvents[] = [
                'id' => $log['id'],
                'action' => $log['action'],
                'module' => $log['module'],
                'username' => $log['username'] ?: ($log['entity_name'] ?: 'Unknown User'),
                'details' => $detailsDecoded ?: $log['details'],
                'created_at' => $log['created_at']
            ];
        }

        Response::json([
            'ok' => true,
            'forensics' => [
                'ip_address' => $targetIp,
                'is_local_ip' => $isLocal,
                'ip_type' => $isLocal ? 'Local LAN / Host Connection' : 'Public Remote Internet',
                'user_agent' => $uaString,
                'os' => $os,
                'browser' => $browser,
                'first_seen' => $firstSeen ?: ($history['created_at'] ?? 'N/A'),
                'last_seen' => $lastSeen ?: ($history['created_at'] ?? 'N/A'),
                'threat_type' => $threatType,
                'attack_classification' => $threatType,
                'classification_label' => $labelMap[$threatType] ?? 'Security Incident',
                'incident_severity' => $severity,
                'severity' => $severity,
                'description' => $description,
                'total_failed_attempts' => $totalFailed,
                'failed_attempts' => $totalFailed,
                'distinct_targets_count' => $distinctCount,
                'target_users' => $uniqueTargets,
                'targeted_accounts' => $uniqueTargets,
                'action_types' => $actionTypes,
                'is_locked' => $isLocked,
                'locked_until' => $lockedUntil,
                'is_banned' => ($banInfo !== null),
                'ban_info' => $banInfo,
                'recent_events' => $formattedEvents
            ]
        ]);
    }
}

